changeSet.sql:
-- Drop the parent lineage (column + its self-FK + old-name indexes
-- rebuilt below).
ALTER TABLE variation DROP CONSTRAINT IF EXISTS fk_variation_parent;
ALTER TABLE variation DROP COLUMN IF EXISTS parent_variation_id;

-- Rename tables.
ALTER TABLE variation RENAME TO sketch;
ALTER TABLE variation_revision RENAME TO sketch_revision;

-- Rename columns.
ALTER TABLE sketch RENAME COLUMN variation_id TO sketch_id;
ALTER TABLE sketch_revision RENAME COLUMN variation_id TO sketch_id;
ALTER TABLE snippet RENAME COLUMN canon_variation_id TO canon_sketch_id;

-- Rename constraints + indexes to match (Postgres keeps old names on
-- rename; keep them tidy so future migrations read cleanly).
ALTER TABLE sketch RENAME CONSTRAINT fk_variation_snippet TO fk_sketch_snippet;
ALTER TABLE sketch_revision RENAME CONSTRAINT fk_variation_revision_variation TO fk_sketch_revision_sketch;
ALTER TABLE snippet RENAME CONSTRAINT fk_snippet_canon_variation TO fk_snippet_canon_sketch;

ALTER INDEX idx_variation_snippet_ordinal RENAME TO idx_sketch_snippet_ordinal;
ALTER INDEX idx_variation_snippet_canon   RENAME TO idx_sketch_snippet_canon;
ALTER INDEX idx_variation_updated         RENAME TO idx_sketch_updated;
ALTER INDEX idx_variation_revision_variation RENAME TO idx_sketch_revision_sketch;
-- 016's soft-delete index.
ALTER INDEX idx_variation_deleted_at RENAME TO idx_sketch_deleted_at;

-- A sketch's home scratchpad (nullable; Go backfill then creation-time set).
ALTER TABLE sketch ADD COLUMN scratchpad_id INTEGER
    REFERENCES scratchpad(scratchpad_id) ON DELETE SET NULL;
CREATE INDEX idx_sketch_scratchpad ON sketch(scratchpad_id) WHERE scratchpad_id IS NOT NULL;
